import time
import numpy as np

def _max_cos(x):
    g = x @ x.T
    np.fill_diagonal(g, -2.0)
    return float(g.max())

def _stress_counts(X, beta=350.0, tol=5e-4):
    G = X @ X.T
    np.fill_diagonal(G, -2.0)
    m = float(G.max())
    # stress (softmax row sum)
    try:
        W = np.exp(beta * (G - m))
        np.fill_diagonal(W, 0.0)
        stress = W.sum(axis=1)
    except Exception:
        stress = G.max(axis=1)
    cnt = (G > m - tol).sum(axis=1)
    pmax = G.max(axis=1)
    return m, stress, cnt, pmax, G

def _anneal(X, steps, b0, b1, lr0, mu, deadline=None):
    n, d = X.shape
    v = np.zeros_like(X)
    if b1 > b0:
        lb = np.log(b1 / b0)
    else:
        lb = 0.0
    for t in range(steps):
        if deadline is not None and (t & 127) == 0 and time.time() > deadline:
            break
        frac = t / max(1, steps - 1)
        beta = b0 * np.exp(lb * frac)
        lr = lr0 * (1.0 - 0.5 * frac)
        G = X @ X.T
        np.fill_diagonal(G, -2.0)
        gmax = G.max()
        W = np.exp(beta * (G - gmax))
        np.fill_diagonal(W, 0.0)
        S = W.sum(axis=1, keepdims=True) + 1e-300
        A = (W @ X) / S
        dot = (A * X).sum(axis=1, keepdims=True)
        Gt = A - dot * X
        v = mu * v + Gt
        vd = (v * X).sum(axis=1, keepdims=True)
        v -= vd * X
        X = X - lr * v
        nr = np.linalg.norm(X, axis=1, keepdims=True)
        np.maximum(nr, 1e-12, out=nr)
        X /= nr
    return X

def _add_holes(Xrem, k, rng, n_cand=9000):
    Xa = Xrem.copy()
    for _ in range(k):
        cand = rng.standard_normal((n_cand, 4))
        cand /= np.maximum(np.linalg.norm(cand, axis=1, keepdims=True), 1e-12)
        best_s = 2.0
        best_p = None
        bs = 3000
        for a in range(0, n_cand, bs):
            cc = cand[a:a+bs]
            dd = cc @ Xa.T
            mm = dd.max(axis=1)
            j = int(np.argmin(mm))
            if float(mm[j]) < best_s:
                best_s = float(mm[j])
                best_p = cc[j]
        jp = best_p + 0.003 * rng.standard_normal(4)
        nrm = np.linalg.norm(jp)
        if not np.isfinite(nrm) or nrm < 1e-12:
            jp = best_p
            nrm = np.linalg.norm(jp)
        jp /= max(1e-12, nrm)
        Xa = np.vstack([Xa, jp.reshape(1, 4)])
    return Xa

def _sig_vec(X, L=600):
    n = X.shape[0]
    iu = np.triu_indices(n, 1)
    c = (X @ X.T)[iu]
    m = c.max()
    s = m - c
    s = np.sort(s)
    if len(s) > L:
        s = s[:L]
    # log scale for comparison, clip
    return np.log10(np.maximum(s, 1e-16))

def _sig_dist(a, b):
    return float(np.mean((a - b) ** 2))

def _lp_polish(x, deadline):
    try:
        from scipy.optimize import linprog
        from scipy.sparse import coo_matrix
    except Exception:
        return x
    x = x / np.maximum(np.linalg.norm(x, axis=1, keepdims=True), 1e-12)
    n, d = x.shape
    try:
        best = _max_cos(x)
    except Exception:
        return x
    radius = 1e-3
    iu = np.triu_indices(n, 1)
    while time.time() < deadline and radius > 1e-14:
        c = (x @ x.T)[iu]
        mval = c.max()
        sel = c > mval - max(20 * radius, 1e-9)
        I, J = iu[0][sel], iu[1][sel]
        p = len(I)
        if p == 0:
            break
        nv = n * d + 1
        try:
            rows = np.repeat(np.arange(p), 2 * d + 1)
            cols = np.concatenate([I[:, None] * d + np.arange(d), J[:, None] * d + np.arange(d), np.full((p, 1), n * d)], 1).ravel()
            vals = np.concatenate([x[J], x[I], -np.ones((p, 1))], 1).ravel()
            A_ub = coo_matrix((vals, (rows, cols)), shape=(p, nv)).tocsr()
            A_eq = coo_matrix((x.ravel(), (np.repeat(np.arange(n), d), np.arange(n * d))), shape=(n, nv)).tocsr()
            obj = np.zeros(nv); obj[-1] = 1.0
            res = linprog(obj, A_ub=A_ub, b_ub=-c[sel], A_eq=A_eq, b_eq=np.zeros(n),
                          bounds=[(-radius, radius)] * (n * d) + [(None, None)], method="highs")
        except Exception:
            break
        if getattr(res, "status", 1) != 0:
            radius *= 0.5
            continue
        try:
            y = x + res.x[:-1].reshape(n, d)
        except Exception:
            radius *= 0.5
            continue
        y /= np.maximum(np.linalg.norm(y, axis=1, keepdims=True), 1e-12)
        vv = _max_cos(y)
        if vv < best:
            x, best, radius = y, vv, min(radius * 1.5, 0.05)
        else:
            radius *= 0.5
    return x

