        try:
            m, nc, deg, _ = _contact_info(Xp)
        except Exception:
            return None
        std = float(deg.std())
        ratt = int((deg == 0).sum())
        bal = std + 5.0 * ratt + 0.02 * float(deg.max() - deg.min())
        h = tuple(sorted(deg.tolist()))
