    best_val = 1e9
    X_best = None
    for rec in picked:
        Xp = rec[3]
        v = rec[0]
        if v < best_val:
            best_val = v
            X_best = Xp.copy()

    # final LP polish of best 2-3 distinct graphs within last ~30s
    final_deadline = t0 + TLIM - 1.5
    per = (final_deadline - time.time()) / max(1, len(picked))
    per = min(per, 12.0)
    for k, rec in enumerate(picked):
        if time.time() > final_deadline - 0.5:
            break
        dl = min(time.time() + per, final_deadline)
        try:
            Y = _lp_polish_deadline(rec[3].copy(), dl)
            vy = _max_cos(Y)
            if vy < best_val:
                best_val = vy
                X_best = Y.copy()
        except Exception:
            continue

    # fallback to incumbent only now
    try:
        for fn in ("best.npy", "record.npy"):
            try:
                a = np.load(fn)
                a = np.asarray(a, dtype=np.float64)
                if a.shape == (n, d) and np.all(np.isfinite(a)):
                    nr = np.linalg.norm(a, axis=1, keepdims=True)
                    if np.min(nr) > 1e-9:
                        a = a / nr
                        va = _max_cos(a)
                        if va < best_val:
                            best_val = va
                            X_best = a.copy()
            except Exception:
                continue
    except Exception:
        pass

    if X_best is None:
        X_best = _normr(rng.standard_normal((n, d)))
    return _normr(np.asarray(X_best, dtype=np.float64))

import time
import numpy as np

def _max_cos(x):
    g = x @ x.T
    np.fill_diagonal(g, -2.0)
    return float(g.max())

def _normr(A):
    n = np.linalg.norm(A, axis=1, keepdims=True)
    n = np.maximum(n, 1e-12)
    return A / n

def _lp_polish_deadline(x, deadline):
    try:
        from scipy.optimize import linprog
        from scipy.sparse import coo_matrix
    except Exception:
        return x
    x = _normr(x)
    n, d = x.shape
    try:
        best = _max_cos(x)
    except Exception:
        return x
    radius = 1e-3
    iu = np.triu_indices(n, 1)
    while time.time() < deadline and radius > 1e-14:
        try:
            c = (x @ x.T)[iu]
        except Exception:
            break
        m = float(c.max())
        sel = c > m - max(20*radius, 1e-9)
        I, J = iu[0][sel], iu[1][sel]
        p = len(I)
        if p == 0:
            break
        nv = n*d+1
        try:
            rows = np.repeat(np.arange(p), 2*d+1)
            cols = np.concatenate([I[:, None]*d+np.arange(d), J[:, None]*d+np.arange(d), np.full((p,1), n*d)], 1).ravel()
            vals = np.concatenate([x[J], x[I], -np.ones((p,1))], 1).ravel()
            A_ub = coo_matrix((vals, (rows, cols)), shape=(p, nv)).tocsr()
            A_eq = coo_matrix((x.ravel(), (np.repeat(np.arange(n), d), np.arange(n*d))), shape=(n, nv)).tocsr()
            obj = np.zeros(nv); obj[-1] = 1.0
            res = linprog(obj, A_ub=A_ub, b_ub=-c[sel], A_eq=A_eq, b_eq=np.zeros(n),
                          bounds=[(-radius, radius)]*(n*d)+[(None, None)], method="highs")
        except Exception:
            break
        if getattr(res, "status", 1) != 0:
            radius *= 0.5
            continue
        try:
            y = x+res.x[:-1].reshape(n, d)
        except Exception:
            radius *= 0.5
            continue
        y = _normr(y)
        try:
            vv = _max_cos(y)
        except Exception:
            radius *= 0.5
            continue
        if vv < best:
            x, best, radius = y, vv, min(radius*1.5, 0.05)
        else:
            radius *= 0.5
    return x

def _tangent_basis(x):
    k = int(np.argmax(np.abs(x)))
    B = np.zeros((4,3))
    col = 0
    for j in range(4):
        if j == k:
            continue
        v = np.zeros(4); v[j] = 1.0
        v = v - float(v @ x)*x
        nv = float(np.linalg.norm(v))
        if nv < 1e-12:
            v = np.zeros(4); v[(j+1)%4]=1.0
            v = v - float(v@x)*x
            nv = float(np.linalg.norm(v))
            if nv < 1e-12:
                continue
        B[:, col] = v/nv
        col += 1
    try:
        Q, _ = np.linalg.qr(B)
    except Exception:
        return B
    # re-project
    try:
        Q = Q - np.outer(x, x @ Q)
        Q, _ = np.linalg.qr(Q)
    except Exception:
        pass
    return Q

def solve():
    t0 = time.time()
    TLIM = 170.0
    n, d = 292, 4
    rng = np.random.default_rng(12345)
    # load incumbent
    cands = []
    for fn in ("best.npy", "record.npy"):
        try:
            a = np.load(fn)
            a = np.asarray(a, dtype=np.float64)
            if a.shape == (n, d) and np.all(np.isfinite(a)):
                nr = np.linalg.norm(a, axis=1, keepdims=True)
                if float(nr.min()) > 1e-9:
                    cands.append(a/nr)
        except Exception:
            pass
    if not cands:
        Xb = _normr(rng.standard_normal((n, d)))
    else:
        try:
            vals = [_max_cos(c) for c in cands]
            Xb = cands[int(np.argmin(vals))].copy()
        except Exception:
            Xb = cands[0].copy()
    try:
        best_val = _max_cos(Xb)
    except Exception:
        Xb = _normr(rng.standard_normal((n, d)))
        best_val = _max_cos(Xb)
    X_best = Xb.copy()
