                fg = make_fg(float(alpha), ra, rb, fc, fd)
                try:
                    res = _minimize(fg, y, jac=True, method='L-BFGS-B',
                                    options={'maxiter': int(mi), 'ftol': 1e-12, 'gtol': 1e-7, 'maxfun': 50000})
                    y = res.x
                except Exception:
